  const decisions = [
    {id:"DEC-01",title:"Snowpipe vs orchestrated COPY",use:"Snowpipe for event-driven file arrival and lower orchestration; COPY for controlled windows, manifests, and cross-step coordination.",prove:"Arrival distribution, required latency, notification reliability, replay method, operational ownership, and unit cost.",risks:"Missing notifications, duplicate/resend behavior, partial batch semantics, and cloud-event dependencies."},
    {id:"DEC-02",title:"Snowpipe Streaming vs files",use:"Streaming when row-level latency materially changes business value; files when replay simplicity and batch controls dominate.",prove:"Latency percentile, ordering key, throughput, client recovery, offset ownership, and duplicate tolerance.",risks:"Client/backpressure complexity, schema drift, cross-location recovery, and end-to-end idempotency."},
    {id:"DEC-03",title:"CDC vs timestamp watermark",use:"Log-based CDC when deletes, transaction order, and low latency matter; watermark only when the source contract makes it safe.",prove:"Clock behavior, update/delete capture, log retention, transaction identity, and backfill path.",risks:"Missed rows, source pressure, out-of-order delivery, tombstones, and coexistence cutover."},
    {id:"DEC-04",title:"Streams/Tasks vs Dynamic Tables vs dbt",use:"Dynamic Tables for declarative freshness DAGs; Streams/Tasks for procedural transactions; dbt for software-engineered transformation and promotion.",prove:"Freshness, side effects, test/deploy model, replay, supported SQL, cost, and ownership.",risks:"Refresh fallback, stale streams, partial commits, overlapping schedules, and duplicated orchestration."},
    {id:"DEC-05",title:"Dimensional vs Data Vault",use:"Dimensional for consumption simplicity; Data Vault for auditable multi-source historical integration when complexity is justified.",prove:"Source volatility, history/audit need, consumer latency, team skill, semantic ownership, and load parallelism.",risks:"Mixed grain, vault overengineering, business-rule sprawl, and slow time-to-value."},
    {id:"DEC-06",title:"Service vs delegated user identity",use:"Service identity for bounded machine workloads; delegated identity when end-user policy and audit fidelity are required.",prove:"Row/masking policy, audit requirement, token lifetime, pool design, concurrency, and compensating controls.",risks:"Confused deputy, privilege concentration, stale session context, mapping drift, and token expiry."},
    {id:"DEC-07",title:"Cortex-native vs external model",use:"Cortex-native for governed proximity and simpler operations; external when an approved capability gap justifies data movement and vendor risk.",prove:"Quality benchmark, residency, model terms, latency, cost, observability, fallback, and retention.",risks:"Unsafe transfer, vendor outage, behavioral drift, split telemetry, and contract change."},
    {id:"DEC-08",title:"Agent vs deterministic workflow",use:"Use an agent for bounded reasoning/tool choice; use deterministic routing for known rules and high-impact actions.",prove:"Intent uncertainty, tool count, failure cost, approval boundary, latency/cost budget, and evaluation coverage.",risks:"Loops, unauthorized tools, repeated side effects, non-determinism, and unclear accountability."},
    {id:"DEC-09",title:"Vector retrieval vs graph reasoning",use:"Vector/hybrid retrieval for relevance over content; graph for governed entity relationships and multi-hop traversal.",prove:"Question type, relationship precision, entity quality, provenance, update cost, and explanation need.",risks:"Semantic false positives, graph staleness, entity-resolution errors, and dual-system complexity."}
  ];

